#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXLEN 31          /* maximum accepted length (0x1f) */

int main(int argc, char **argv)
{
    /* ---------- argument check ---------- */
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);

    /* ---------- length checks ---------- */
    if (len == 0 || len > MAXLEN) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ---------- character validation ---------- */
    for (size_t i = 0; i < len; ++i) {
        if (in[i] != '0' && in[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    /* ---------- copy input to mutable tape ---------- */
    char tape[MAXLEN + 1];          /* one extra byte is never used, but keeps the array safe */
    memcpy(tape, in, len);

    /* ---------- Turing‑machine increment ---------- */
    int steps = 0;                  /* counts every write and every head move */
    int pos   = (int)len - 1;       /* head starts on the right‑most cell */
    int overflow = 0;               /* set when the increment would need a new most‑significant bit */

    while (1) {
        if (tape[pos] == '0') {
            /* flip 0 → 1 and stop */
            tape[pos] = '1';
            ++steps;                /* the write */
            break;
        } else {                    /* tape[pos] == '1' */
            /* flip 1 → 0, move left and continue */
            tape[pos] = '0';
            ++steps;                /* the write */
            --pos;
            ++steps;                /* the move */
            if (pos < 0) {          /* we have moved past the leftmost cell */
                overflow = 1;
                break;
            }
        }
    }

    /* ---------- output ---------- */
    if (overflow) {
        puts("OVERFLOW");
        printf(" steps=%d\n", steps);
    } else {
        printf("result=");
        for (size_t i = 0; i < len; ++i)
            putchar(tape[i]);
        printf(" steps=%d\n", steps);
    }

    return 0;
}
